    }
    public async Task<OfferSkuPage> LookupAsync(string requestId,string listingId,string? query,string? cursor,CancellationToken ct)
    {
        requestId=SourcingRules.Id(requestId);listingId=SourcingRules.Id(listingId);var parent=await Parents(null).AsNoTracking().Where(r=>r.Id==requestId).Select(r=>new{r.Id,Model=r.Lines.Where(l=>l.ListingId==listingId).Select(l=>l.ModelId).SingleOrDefault()}).SingleOrDefaultAsync(ct);if(parent?.Model is null)throw Missing();return await catalog.LookupAsync(parent.Model,query,cursor,ct);
    }
    public async Task<OfferSkuSnapshot> ReadSkuAsync(string requestId,string listingId,string variantId,CancellationToken ct)
