        RequireTransaction();var hash=SourcingRules.Payload(new{TargetRequest=requestId,TargetOffer=offerId,RequestVersion=parentVersion,Version=offerVersion,TermsHash=termsHash,SupersedesOfferId=supersedes,SupersedesVersion=supersedesVersion});await CommandLock(actor,"publish",command,null,ct);if(await Replay(actor,"publish",command,requestId,offerId,hash,ct) is{} replay)return replay;await RequestLock(requestId,ct);var parent=await ParentAsync(null,requestId,false,ct);CheckParent(parent,parentVersion);var row=await Graph(Offers(null)).SingleOrDefaultAsync(o=>o.RequestId==requestId&&o.Id==offerId,ct)??throw Missing();CheckOffer(row,offerVersion,termsHash);BoundSnapshot(row);if(row.State!="Draft")throw Conflict();var now=clock.GetUtcNow();if(row.AcceptUntil<=now||row.PurchaseUntil<row.AcceptUntil)throw Expired();
