    }
    public Task<SourcingOfferMutation> WithdrawAsync(string actorId,string requestId,string offerId,SourcingOfferActionInput input,CancellationToken ct)=>ActAsync(actorId,null,requestId,offerId,"withdraw",input,ct);
    public Task<SourcingOfferMutation> AcceptAsync(string ownerId,string requestId,string offerId,SourcingOfferActionInput input,CancellationToken ct)=>ActAsync(ownerId,ownerId,requestId,offerId,"accept",input,ct);
    public Task<SourcingOfferMutation> DeclineAsync(string ownerId,string requestId,string offerId,SourcingOfferActionInput input,CancellationToken ct)=>ActAsync(ownerId,ownerId,requestId,offerId,"decline",input,ct);
    private async Task<SourcingOfferMutation> ActAsync(string actorId,string? ownerId,string requestId,string offerId,string operation,SourcingOfferActionInput supplied,CancellationToken ct)
    {
