    public async Task<SourcingOfferDetail> ReadAsync(string? ownerId,string requestId,string offerId,CancellationToken ct)
    {
        var owner=ownerId is null?null:SourcingRules.Actor(ownerId);requestId=SourcingRules.Id(requestId);offerId=SourcingRules.Id(offerId);
        for(var attempt=0;attempt<2;attempt++){
            var parent=await Parents(owner).AsNoTracking().SingleOrDefaultAsync(r=>r.Id==requestId,ct)??throw Missing();var row=await Graph(Offers(owner).AsNoTracking()).SingleOrDefaultAsync(o=>o.RequestId==requestId&&o.Id==offerId,ct)??throw Missing();BoundSnapshot(row);var now=clock.GetUtcNow();var blocking=await AcceptedBlocks(requestId,now,ct);var blockers=new List<string>();if(!Open(parent.State))blockers.Add("sourcing_state_conflict");if(SourcingOfferRules.EffectiveState(row.State,row.AcceptUntil,row.PurchaseUntil,now)=="Expired")blockers.Add("sourcing_offer_expired_conflict");if(row.State is "Draft" or "Published")blockers.AddRange(await CatalogBlockers(row,row.State=="Draft",ct));if(blocking&&row.State=="Draft")blockers.Add("sourcing_offer_accepted_conflict");
            var latestParent=await Parents(owner).AsNoTracking().Where(r=>r.Id==requestId).Select(r=>r.Version).SingleOrDefaultAsync(ct);var latestOffer=await Offers(owner).AsNoTracking().Where(o=>o.Id==offerId&&o.RequestId==requestId).Select(o=>o.Version).SingleOrDefaultAsync(ct);if(latestParent is null||latestOffer is null)throw Missing();if(!latestParent.SequenceEqual(parent.Version)||!latestOffer.SequenceEqual(row.Version)){if(attempt==0)continue;throw Conflict();}
            now=clock.GetUtcNow();if(SourcingOfferRules.EffectiveState(row.State,row.AcceptUntil,row.PurchaseUntil,now)=="Expired")blockers.Add("sourcing_offer_expired_conflict");var open=Open(parent.State);var activePublished=row.State=="Published"&&row.IsActive&&row.AcceptUntil>now&&open;var valid=blockers.Count==0;var result=new SourcingOfferDetail(1,requestId,Reference(parent),Version(parent.Version),new(Summary(row,now),row.TermsFa,row.TermsEn,row.AcceptanceId,row.Lines.OrderBy(l=>l.LineId,StringComparer.Ordinal).Select(SourcingOfferSnapshots.Read).ToArray()),owner is null&&open&&row.State=="Draft",owner is null&&open&&row.State=="Draft"&&row.AcceptUntil>now&&valid,owner is null&&open&&(row.State=="Draft"||activePublished),owner is not null&&activePublished&&valid,owner is not null&&activePublished,owner is not null&&open&&!blocking,owner is null&&open&&!blocking,blockers.Distinct(StringComparer.Ordinal).ToArray());if(JsonSerializer.SerializeToUtf8Bytes(result,Json).Length>524288)throw Capacity();return result;
        }
