    }
    public async Task<SourcingOfferPage> PageAsync(string? ownerId,string requestId,string? cursor,CancellationToken ct)
    {
        var owner=ownerId is null?null:SourcingRules.Actor(ownerId);requestId=SourcingRules.Id(requestId);var parent=await Parents(owner).AsNoTracking().SingleOrDefaultAsync(r=>r.Id==requestId,ct)??throw Missing();var binding=SourcingRules.Hash("offers:"+(owner??"admin")+":"+requestId);var after=Decode<OfferCursor>(cursor);if(after is not null&&(after.Binding!=binding||after.At<DateTimeOffset.MinValue.UtcTicks||after.At>DateTimeOffset.MaxValue.UtcTicks||SourcingRules.Id(after.Id)!=after.Id))throw InvalidCursor();var query=Offers(owner).AsNoTracking().Where(o=>o.RequestId==requestId);if(after is not null){var at=new DateTimeOffset(after.At,TimeSpan.Zero);query=query.Where(o=>o.CreatedAt<at||o.CreatedAt==at&&string.Compare(o.Id,after.Id)<0);}var size=owner is null?50:20;var found=await query.OrderByDescending(o=>o.CreatedAt).ThenByDescending(o=>o.Id).Take(size+1).Select(o=>new{Row=o,LineCount=o.Lines.Count,ItemCount=o.Lines.Sum(l=>l.Quantity)}).ToArrayAsync(ct);var page=found.Take(size).ToArray();var now=clock.GetUtcNow();var blocking=await AcceptedBlocks(requestId,now,ct);return new(1,requestId,Reference(parent),Version(parent.Version),size,page.Select(r=>Summary(r.Row,now,r.LineCount,r.ItemCount)).ToArray(),found.Length>size?Encode(new OfferCursor(page[^1].Row.CreatedAt.UtcTicks,page[^1].Row.Id,binding)):null,owner is not null&&Open(parent.State)&&!blocking,owner is null&&Open(parent.State)&&!blocking);
    }
    public async Task<SourcingOfferEventPage> EventsAsync(string? ownerId,string requestId,string offerId,string? cursor,CancellationToken ct)
    {
        var owner=ownerId is null?null:SourcingRules.Actor(ownerId);requestId=SourcingRules.Id(requestId);offerId=SourcingRules.Id(offerId);if(!await Parents(owner).AsNoTracking().AnyAsync(r=>r.Id==requestId,ct)||!await Offers(owner).AsNoTracking().AnyAsync(o=>o.RequestId==requestId&&o.Id==offerId,ct))throw Missing();var binding=SourcingRules.Hash("offer-events:"+(owner??"admin")+":"+requestId+":"+offerId);var after=Decode<EventCursor>(cursor);long position=0;if(after is not null&&(after.Binding!=binding||after.After is not {Length:>0 and <=19}||!long.TryParse(after.After,NumberStyles.None,CultureInfo.InvariantCulture,out position)||position<=0))throw InvalidCursor();var size=owner is null?50:20;var found=await db.SourcingOfferEvents.AsNoTracking().Where(e=>e.OfferId==offerId&&(owner==null||e.IsPublic)&&e.Id>position).OrderBy(e=>e.Id).Take(size+1).ToArrayAsync(ct);var page=found.Take(size).ToArray();return new(1,size,page.Select(e=>new SourcingOfferEventData(e.Id.ToString(CultureInfo.InvariantCulture),e.Revision,e.StateBefore,e.StateAfter,e.ActorKind,e.ReasonCode,e.PublicMessage,e.At)).ToArray(),found.Length>size?Encode(new EventCursor(page[^1].Id.ToString(CultureInfo.InvariantCulture),binding)):null);
    }
    public async Task<SourcingOfferMutation> ReadReceiptAsync(string actorId,string requestId,string offerId,string operation,string commandId,CancellationToken ct)
    {
        var actor=SourcingRules.Actor(actorId);requestId=SourcingRules.Id(requestId);offerId=SourcingRules.Id(offerId);var command=SourcingRules.CommandId(commandId);if(!SourcingOfferRules.Operations.Contains(operation,StringComparer.Ordinal))throw Invalid();var row=await db.SourcingOfferCommandReceipts.AsNoTracking().SingleOrDefaultAsync(r=>r.ActorId==actor&&r.Operation==operation&&r.CommandId==command&&r.RequestId==requestId&&r.OfferId==offerId&&(allowDemo||!r.ContainsDemo),ct)??throw Missing();return Deserialize(row) with{Replayed=true};
