    private async Task NotifyPublication(SourcingRequest parent,SourcingOffer offer,DateTimeOffset at,CancellationToken ct)
    {
        var requested=await db.SourcingRequestLines.AsNoTracking().Where(l=>l.RequestId==parent.Id&&l.PhoneConfigurationJson!=null).Select(l=>new{l.ListingId,l.PhoneConfigurationJson}).ToArrayAsync(ct);
        if(requested.Length>0&&phoneNotifications is null)throw new BusinessException("phone_discovery_unavailable","Phone offer notifications are not configured.");
        foreach(var line in requested){var configuration=JsonSerializer.Deserialize<PhoneConfigurationSnapshot>(line.PhoneConfigurationJson!,Json)??throw Capacity();var id=SourcingRules.Hash("phone-offer:"+offer.Id+":"+configuration.Id)[..32].ToLowerInvariant();await phoneNotifications!.RecordAsync(new(id,parent.OwnerId,"sourcing_offer_published",line.ListingId,configuration.Id,parent.Id,offer.Id,null,null,at),ct);}
    }
    private async Task<string[]> CatalogBlockers(SourcingOffer row,bool exactCurrent,CancellationToken ct)
    {
        var current=await catalog.ReadAsync(row.Lines.Select(l=>l.VariantId).Distinct(StringComparer.OrdinalIgnoreCase).ToArray(),ct);if(row.Lines.Any(l=>!current.TryGetValue(l.VariantId,out var sku)||sku.ProductId!=l.ProductId||sku.MaterialFingerprint!=l.MaterialFingerprint||exactCurrent&&sku.CurrentFingerprint!=l.CurrentFingerprint))return ["sourcing_offer_catalog_conflict"];
        var methods=await purchasing.MethodsAsync("fa",ct);var plans=await purchasing.PlansAsync("fa",ct);if(methods.Count>64||plans.Count>64||methods.Any(m=>m.CategoryIds.Length>500)||plans.Any(p=>p.CategoryIds.Length>500))throw Capacity();var variants=current.Values.ToArray();var eligiblePlans=plans.Where(p=>p.Enabled&&InRange(row.TotalRial,p.MinAmountRial,p.MaxAmountRial)&&variants.All(v=>(p.CategoryIds.Length==0||p.CategoryIds.Contains(v.Model.CategoryId))&&(v.ChequePlanIds.Length==0||v.ChequePlanIds.Contains(p.Id)))).ToArray();var eligible=methods.Any(m=>m.Enabled&&InRange(row.TotalRial,m.MinAmountRial,m.MaxAmountRial)&&variants.All(v=>v.ProductMethodIds.Contains(m.Id)&&(v.VariantMethodIds is null||v.VariantMethodIds.Contains(m.Id))&&(m.CategoryIds.Length==0||m.CategoryIds.Contains(v.Model.CategoryId)))&&(m.Kind!="cheque"||eligiblePlans.Length>0));return eligible?[]:["sourcing_offer_purchase_conflict"];
    }
    private static bool InRange(long amount,long? min,long? max)=>(min is null||amount>=min)&&(max is null||amount<=max);
    private Task<bool> AcceptedBlocks(string requestId,DateTimeOffset now,CancellationToken ct)=>db.SourcingOffers.AsNoTracking().AnyAsync(o=>o.RequestId==requestId&&o.IsActive&&o.State=="Accepted"&&o.PurchaseUntil>now,ct);
    // Read one sentinel beyond every persisted technical bound. Corrupt or
    // restored data fails explicitly instead of hydrating an unbounded graph.
    private static IQueryable<SourcingOffer> Graph(IQueryable<SourcingOffer> query)=>query.Include(o=>o.Lines.OrderBy(l=>l.LineId).Take(65)).ThenInclude(l=>l.Images.OrderBy(i=>i.SortOrder).Take(25)).Include(o=>o.Lines.OrderBy(l=>l.LineId).Take(65)).ThenInclude(l=>l.Attributes.OrderBy(a=>a.Scope).ThenBy(a=>a.AttributeId).Take(129)).ThenInclude(a=>a.Options.OrderBy(v=>v.OptionId).Take(65)).Include(o=>o.Lines.OrderBy(l=>l.LineId).Take(65)).ThenInclude(l=>l.PurchaseRules.OrderBy(r=>r.Kind).ThenBy(r=>r.RuleId).Take(193)).AsSplitQuery();
    private static void CheckParent(SourcingRequest row,string version){if(Version(row.Version)!=version)throw new BusinessException("version_conflict","The sourcing request changed. Read its current version.");if(!Open(row.State))throw new BusinessException("sourcing_state_conflict","The sourcing request is closed.");}
    private static void CheckOffer(SourcingOffer row,string version,string termsHash){if(Version(row.Version)!=version)throw new BusinessException("version_conflict","The offer changed. Read its current version.");if(row.TermsHash!=termsHash)throw new BusinessException("sourcing_offer_terms_conflict","The offer terms changed. Review the current snapshot.");}
    private void TouchParent(SourcingRequest parent,string actor,string kind,string reason,DateTimeOffset now)
    {
        var before=parent.State;if(parent.State=="Submitted")parent.State="Reviewing";
        parent.ChangedAt=now;db.Entry(parent).Property(r=>r.ChangedAt).IsModified=true;
        // Request schema1 records state transitions only. Its strict clients do
        // not accept Reviewing→Reviewing; child events own offer-only actions.
        if(before!=parent.State)db.SourcingRequestEvents.Add(new(){RequestId=parent.Id,ActorId=actor,ActorKind=kind,StateBefore=before,StateAfter=parent.State,ReasonCode=reason,At=now});
    }
    private SourcingOfferEvent Event(SourcingOffer offer,string actor,string kind,string? before,string reason,bool isPublic,DateTimeOffset now){var row=new SourcingOfferEvent{OfferId=offer.Id,Revision=offer.Revision,ActorId=actor,ActorKind=kind,StateBefore=before,StateAfter=offer.State,ReasonCode=reason,IsPublic=isPublic,At=now};db.SourcingOfferEvents.Add(row);return row;}
    private static SourcingOfferSummary Summary(SourcingOffer row,DateTimeOffset now,int? count=null,int? quantity=null)=>new(row.Id,row.Revision,row.State,SourcingOfferRules.EffectiveState(row.State,row.AcceptUntil,row.PurchaseUntil,now),Version(row.Version),row.TermsHash,row.TotalRial.ToString(CultureInfo.InvariantCulture),count??row.Lines.Count,quantity??row.Lines.Sum(l=>l.Quantity),row.AcceptUntil,row.PurchaseUntil,row.ExpectedAt,row.CreatedAt,row.ChangedAt,row.PublishedAt,row.AcceptedAt,row.ContainsDemo);
    private static void BoundSnapshot(SourcingOffer row){if(row.Lines.Count is <1 or >64||row.Lines.Any(l=>l.Images.Count>24||l.Attributes.Count>128||l.Attributes.GroupBy(a=>a.Scope).Any(g=>g.Count()>64)||l.Attributes.Any(a=>a.Options.Count>64)||l.PurchaseRules.Count>192)||JsonSerializer.SerializeToUtf8Bytes(new{row.TermsFa,row.TermsEn,Lines=row.Lines.OrderBy(l=>l.LineId,StringComparer.Ordinal).Select(SourcingOfferSnapshots.Read).ToArray()},Json).Length>524288-16384)throw Capacity();}
    private async Task<SourcingOfferMutation?> Replay(string actor,string operation,string command,string requestId,string offerId,string hash,CancellationToken ct){var row=await db.SourcingOfferCommandReceipts.AsNoTracking().SingleOrDefaultAsync(r=>r.ActorId==actor&&r.Operation==operation&&r.CommandId==command,ct);if(row is null)return null;if(row.ContainsDemo&&!allowDemo)throw Missing();if(row.RequestId!=requestId||row.OfferId!=offerId||row.PayloadHash!=hash)throw new BusinessException("idempotency_conflict","This offer command id was used for another target or payload.");return Deserialize(row) with{Replayed=true};}
    private static SourcingOfferMutation Deserialize(SourcingOfferCommandReceipt row)=>JsonSerializer.Deserialize<SourcingOfferMutation>(row.ResultJson,Json)??throw new InvalidOperationException("Saved offer command result is invalid.");
    private async Task<SourcingOfferMutation> Remember(string actor,string operation,string command,string hash,SourcingRequest parent,SourcingOffer offer,SourcingOfferEvent ev,CancellationToken ct){var result=new SourcingOfferMutation(1,parent.Id,offer.Id,operation,offer.Revision,offer.State,Version(offer.Version),Version(parent.Version),ev.Id.ToString(CultureInfo.InvariantCulture),offer.AcceptanceId,ev.At,false);var json=JsonSerializer.Serialize(result,Json);if(Encoding.Unicode.GetByteCount(json)>16384)throw Capacity();db.SourcingOfferCommandReceipts.Add(new(){ActorId=actor,Operation=operation,CommandId=command,RequestId=parent.Id,OfferId=offer.Id,PayloadHash=hash,ResultJson=json,ContainsDemo=offer.ContainsDemo,CreatedAt=clock.GetUtcNow()});await db.SaveChangesAsync(ct);return result;}
    private async Task CommandLock(string actor,string operation,string command,string? owner,CancellationToken ct){if(owner is not null)await Lock("owner:"+owner.ToUpperInvariant(),ct);await Lock("offer-command:"+actor.ToUpperInvariant()+":"+operation+":"+command,ct);}
    private Task RequestLock(string id,CancellationToken ct)=>Lock("request:"+id,ct);
    private async Task Lock(string key,CancellationToken ct){var transaction=db.Database.CurrentTransaction??throw new InvalidOperationException("Offer application locks require the root transaction.");await using var command=db.Database.GetDbConnection().CreateCommand();command.Transaction=transaction.GetDbTransaction();command.CommandTimeout=15;command.CommandText="DECLARE @result int; EXEC @result=sys.sp_getapplock @Resource=@resource,@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=10000; SELECT @result;";var parameter=command.CreateParameter();parameter.ParameterName="@resource";parameter.Value="sayman:market:sourcing:"+SourcingRules.Hash(key);command.Parameters.Add(parameter);if(Convert.ToInt32(await command.ExecuteScalarAsync(ct),CultureInfo.InvariantCulture)<0)throw new BusinessException("sourcing_busy_conflict","Another sourcing command is in progress. Retry the same command id.");}
    private static string Encode<T>(T value)=>Convert.ToBase64String(JsonSerializer.SerializeToUtf8Bytes(value,Json)).TrimEnd('=').Replace('+','-').Replace('/','_');
    private static T? Decode<T>(string? cursor)where T:class{if(cursor is null)return null;try{if(cursor.Length is <1 or >200||cursor.Any(c=>!char.IsAsciiLetterOrDigit(c)&&c is not ('-' or '_')))throw InvalidCursor();var raw=cursor.Replace('-','+').Replace('_','/');return JsonSerializer.Deserialize<T>(Convert.FromBase64String(raw.PadRight((raw.Length+3)/4*4,'=')),Json)??throw InvalidCursor();}catch(Exception e)when(e is FormatException or JsonException or ArgumentException){throw InvalidCursor();}}
    private static BusinessException Invalid()=>new("invalid_sourcing_offer","Use the current versions, explicit offer target and bounded offer fields.");
    private static BusinessException InvalidCursor()=>new("invalid_sourcing_offer_cursor","Use the cursor belonging to this owner, request and offer.");
    private static BusinessException Missing()=>new("not_found","The sourcing offer was not found.");
    private static BusinessException Conflict()=>new("sourcing_offer_state_conflict","The offer or request state changed. Read the current detail before editing.");
    private static BusinessException Expired()=>new("sourcing_offer_expired_conflict","The offer deadline has passed. A new offer is required.");
    private static BusinessException Capacity()=>new("sourcing_offer_capacity_unavailable","The offer snapshot or configuration exceeds its supported bounds.");
}
